insert before first.source:
cicada 2
tempo 120
track bass acid { cutoff=700Hz }
pattern riff acid steps=4 { 1 . 5 . }
scene main { bass=riff }
song { main*4 }
// keep this
automate bass.cutoff {
  @1.1.1 400Hz // low
    @1.2.1 500Hz linear
@5.1.1 1600Hz smooth // high
}

